from itertools import count

def find_numbers():
    numbers = []
    for n in count(2):
        for i in range(10**(n-1), 10**n):
            digit_sum = sum(int(digit) for digit in str(i))
            if i % digit_sum == 9*n - 2:
                numbers.append((n, i))
                if len(numbers) == 6:
                    break
        if len(numbers) == 6:
